import { useParams } from 'react-router-dom'
import Footer from '../../components/Footer'
import Banner from '../../components/Banner'
import HeaderAlternativo from '../../components/Header/HeaderAlternativo'
import ProductsList from '../../components/ProductsList'
import { sndPage, promocoes } from '../../models/data' // Importando os pratos novos do arquivo data.ts

const Prato1 = () => {
  const { pratoId } = useParams<string>() // Obtendo o id do prato da URL

  // Busca o prato específico na lista 'promocoes'
  const prato = promocoes.find(
    (prato) => prato.id === parseInt(pratoId || '', 10)
  )

  if (!prato) {
    return <div>Prato não encontrado!</div> // Caso não encontre o prato, exibe uma mensagem de erro
  }

  // Passar a primeira informação de 'infos' como 'info'
  const info = prato.infos ? prato.infos[0] : ''

  return (
    <>
      <HeaderAlternativo />
      {/* Passando a imagem do prato clicado para o Banner */}
      <Banner image={prato.image} title={prato.title} info={info} />
      <ProductsList pratos={sndPage} title="Novos Pratos" background="gray" />
      <Footer />
    </>
  )
}

export default Prato1
